            return err_try_help(
                f"invalid value '{shell}' for '<SHELL>'",
                extra="  [possible values: bash, elvish, fish, powershell, zsh]\n",
            )
        if len(args) > 1:
            return err_try_help(f"unexpected argument '{args[1]}' found", usage=f"{prog()} completion <SHELL>")
        sys.stdout.write(COMPLETIONS.get(shell, ""))
        return 0
    if name == "help":
        if not args:
            print_main_help()
            return 0
        sub = args[0]
