    # not meaningful for documented use; saturate them harmlessly to zero.
    if not math.isfinite(x) or x <= 0:
        return 0
    return int(x)


def render(text: str, hscale: float = 1.0, vscale: float = 1.0, padding: Optional[int] = None) -> str:
    lines = rust_lines(text)
    if not lines:
        return ""
