    except SystemExit as ex:
        return int(ex.code)
    if parsed is None:
        return rc
    if parsed.command is not None:
        return handle_command(parsed.command)
    text, rc = read_input(parsed.file, parsed.encoding)
    if rc != 0 or text is None:
        return rc
    sys.stdout.write(render(text, parsed.hscale, parsed.vscale, parsed.padding))
    return 0


