                val = a.split("=", 1)[1]
            else:
                sc = split_short_cluster(a)
                if sc and sc[0] == "-V":
                    val = sc[1] or ""
                else:
                    val = need_value(a, "--vertical-scale <VSCALE>")
            try:
                p.vscale = parse_float_value(val, "--vertical-scale <VSCALE>")
            except ValueError as ex:
                return None, err_try_help(str(ex))
            i += 1
            continue

        if not after_dd and (a == "--padding" or a.startswith("--padding=")):
            if a.startswith("--padding="):
                val = a.split("=", 1)[1]
            else:
                val = need_value(a, "--padding <PADDING>")
            try:
                p.padding = parse_padding_value(val)
            except ValueError as ex:
                return None, err_try_help(str(ex))
            i += 1
            continue

        if not after_dd and (a == "--encoding" or a.startswith("--encoding=")):
            if a.startswith("--encoding="):
                val = a.split("=", 1)[1]
            else:
                val = need_value(a, "--encoding <ENCODING>")
            if val not in ENCODINGS:
                return None, err_try_help(
                    f"invalid value '{val}' for '--encoding <ENCODING>'",
                    extra="  [possible values: utf8-lossy, utf8]\n",
                )
            p.encoding = val
            i += 1
            continue

        if not after_dd and a.startswith("-") and a != "-":
            # Negative separate values and unknown flags both land here.
            tip = ""
            if a.startswith("--"):
                tip = f"\n  tip: to pass '{a}' as a value, use '-- {a}'\n"
            else:
                tip = f"\n  tip: to pass '{a}' as a value, use '-- {a}'\n"
            return None, err_try_help(f"unexpected argument '{a}' found", usage=f"{prog()} [OPTIONS] [FILE] [COMMAND]", extra=tip)

        positional.append(a)
        i += 1

    # Interpret positionals: optional FILE, then optional COMMAND; command names are recognized
    # in either first or second positional slot as clap does for this command layout.
    if positional:
        if positional[0] in ("completion", "help"):
            p.command = (positional[0], positional[1:])
        elif len(positional) >= 2 and positional[1] in ("completion", "help"):
            p.file = positional[0]
            p.command = (positional[1], positional[2:])
        else:
            p.file = positional[0]
            if len(positional) > 1:
                return None, err_try_help(f"unexpected argument '{positional[1]}' found", usage=f"{prog()} [OPTIONS] [FILE] [COMMAND]")
    return p, 0


def handle_command(command: Tuple[str, List[str]]) -> int:
    name, args = command
    if name == "completion":
        if not args:
            return err_try_help(
                "the following required arguments were not provided:\n  <SHELL>",
                usage=f"{prog()} completion <SHELL>",
            )
        if args[0] in ("-h", "--help"):
            print_completion_help()
            return 0
        shell = args[0]
        if shell not in SHELLS:
            return err_try_help(
                f"invalid value '{shell}' for '<SHELL>'",
                extra="  [possible values: bash, elvish, fish, powershell, zsh]\n",
            )
        if len(args) > 1:
            return err_try_help(f"unexpected argument '{args[1]}' found", usage=f"{prog()} completion <SHELL>")
        sys.stdout.write(COMPLETIONS.get(shell, ""))
        return 0
    if name == "help":
        if not args:
            print_main_help()
            return 0
        sub = args[0]
        if sub == "completion":
            if len(args) > 1:
                return err_try_help(f"unrecognized subcommand '{args[1]}'", usage=f"{prog()} completion <SHELL>")
            print_completion_help()
            return 0
        if sub == "help":
            if len(args) > 1:
                return err_try_help(f"unrecognized subcommand '{args[1]}'", usage=f"{prog()} [OPTIONS] [FILE] [COMMAND]")
            print_main_help()
            return 0
        return err_try_help(f"unrecognized subcommand '{sub}'", usage=f"{prog()} [OPTIONS] [FILE] [COMMAND]")
    return 2


def rust_lines(text: str) -> List[str]:
    if text == "":
        return []
    parts = text.split("\n")
    # str::lines does not yield a final empty line for a trailing LF.
    if parts and parts[-1] == "":
        parts.pop()
    # A CR immediately before LF is stripped from each yielded line.
    return [part[:-1] if part.endswith("\r") else part for part in parts]


def char_byte_indices(s: str):
    off = 0
    for ch in s:
        yield off, ch
        off += len(ch.encode("utf-8"))


def line_span(line: str) -> Tuple[Optional[int], Optional[int], int]:
    first: Optional[int] = None
    last: Optional[int] = None
    for off, ch in char_byte_indices(line):
        if not ch.isspace():
            if first is None:
                first = off
            last = off
    if first is None or last is None:
        return None, None, 0
    return first, last, last + 1


def trunc_float_to_usize(x: float) -> int:
    # Rust's positive float-to-usize casts truncate toward zero. Negative/NaN behavior is
    # not meaningful for documented use; saturate them harmlessly to zero.
    if not math.isfinite(x) or x <= 0:
        return 0
    return int(x)


def render(text: str, hscale: float = 1.0, vscale: float = 1.0, padding: Optional[int] = None) -> str:
    lines = rust_lines(text)
    if not lines:
        return ""
    hv = hscale
    vv = vscale if vscale < 1.0 else 1.0
    if not math.isfinite(hv):
        hv = 0.0 if hv != float("inf") else 1.0
    if not math.isfinite(vv):
        vv = 1.0
    if vv < 0:
        vv = 0.0

    spans = [line_span(line) for line in lines]
    last_y = trunc_float_to_usize((len(lines) - 1) * vv)
    row_pixels: List[Set[int]] = [set() for _ in range(last_y + 1)]
    row_widths: List[int] = [0 for _ in range(last_y + 1)]

    for idx, (start, end, width) in enumerate(spans):
        y = trunc_float_to_usize(idx * vv)
        src_width = width if width > 0 else 1
        scaled_width = trunc_float_to_usize(src_width * hv)
        if scaled_width > row_widths[y]:
            row_widths[y] = scaled_width
        if start is not None and end is not None:
            sx0 = trunc_float_to_usize(start * hv)
            sx1 = trunc_float_to_usize((end + 1) * hv) - 1
            # Respect the scaled row width if floating round-off would exceed it.
            if sx1 >= scaled_width:
                sx1 = scaled_width - 1
            if sx1 >= sx0:
                row_pixels[y].update(range(sx0, sx1 + 1))

    out_lines: List[str] = []
    for block in range((len(row_pixels) + 3) // 4):
        y0 = block * 4
        block_width = 0
        for r in range(4):
            yy = y0 + r
            if yy < len(row_widths):
                block_width = max(block_width, row_widths[yy])
        cells = (block_width + 1) // 2
        chars: List[str] = []
        for cx in range(cells):
            bits = 0
            for r in range(4):
                yy = y0 + r
                if yy >= len(row_pixels):
                    continue
                pix = row_pixels[yy]
                x_left = cx * 2
                if x_left in pix:
                    bits |= DOT_BITS[r][0]
                if x_left + 1 in pix:
                    bits |= DOT_BITS[r][1]
            chars.append(chr(0x2800 + bits))
        if padding is not None and len(chars) < padding:
            chars.extend(" " * (padding - len(chars)))
        out_lines.append("".join(chars))
    return "\n".join(out_lines) + "\n"


def read_input(path: Optional[str], encoding: str) -> Tuple[Optional[str], int]:
    try:
        if path is None:
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as f:
                data = f.read()
    except OSError as ex:
        eprint(f"code-minimap: {ex.strerror} (os error {ex.errno})\n")
        return None, 1
    if encoding == "utf8":
        try:
            return data.decode("utf-8"), 0
        except UnicodeDecodeError:
            eprint("code-minimap: stream did not contain valid UTF-8\n")
            return None, 1
    return data.decode("utf-8", "replace"), 0


def main(argv: Sequence[str]) -> int:
    try:
        parsed, rc = parse_args(argv)
    except SystemExit as ex:
        return int(ex.code)
    if parsed is None:
        return rc
    if parsed.command is not None:
        return handle_command(parsed.command)
    text, rc = read_input(parsed.file, parsed.encoding)
    if rc != 0 or text is None:
        return rc
    sys.stdout.write(render(text, parsed.hscale, parsed.vscale, parsed.padding))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
